#!/usr/bin/env python3
"""Relatório científico descritivo e catálogo das figuras B1."""
import json
from pathlib import Path
import pandas as pd

OUT=Path(__file__).resolve().parents[1]
S=pd.read_csv(OUT/'processed/summary.csv').set_index('id')
I=pd.read_csv(OUT/'inventario_execucoes.csv').fillna('')
M=json.loads((OUT/'manifest.json').read_text())
V=json.loads((OUT/'validation/checks.json').read_text())
def v(k,col,d=2):return f'{S.loc[k,col]:.{d}f}'
def typ(path):
    p=Path(path);n=p.stem
    if 'painel_completo' in n:return ('Painel individual completo','HTTP individual, CPU, memória, workers, espera, duração, RPS e rede','eventos HTTP e computacionais; Docker; captura','Séries no tempo relativo; ataque sombreado','Separa resposta de timeout; mostra residual após 60 s','Densidade elevada em A4/F3–F5; dados pontuais não interpolados')
    if 'painel_compacto' in n:return ('Painel individual compacto','HTTP ativos no cliente, CPU, memória, workers e duração','HTTP; eventos da vítima; Docker','Contagem ativa por intervalo HTTP; demais dados pontuais/eventos','Realça simultaneidade e residual','HTTP ativo no cliente não significa handler ativo')
    if 'piloto' in n:return ('Comparação com piloto A1','RPS nominal, iniciado e encerrado','configuração efetiva; request_log','30 s por taxa; encerramento atribuído ao instante do fim','A1 é mostrado apenas como perspectiva adicional','B1.1 não é repetição controlada da B1.2')
    if 'rps_nominal_efetivo' in n:return ('Intensidade nominal e efetiva','RPS configurado, início e fim HTTP','effective_config; request_log','Contagens em [30,60) divididas por 30 s','Flooding perde correspondência nominal após F2','Início e fim são eventos distintos; não confundir término após 60 s com perda')
    if 'fracao_taxa' in n:return ('Fração da taxa nominal','RPS iniciado / nominal','effective_config; request_log','Razão de taxas com mesma janela de 30 s','F3–F5 apresentam queda da fração realizada','Não é eficiência computacional da vítima')
    if 'cpu_por_operacao' in n:return ('Custo individual computacional','CPU do processo worker por operação (ms)','work_completed.work_cpu_seconds','Boxplot por execução; bigodes p5–p95','Custos distintos decorrem também de endpoints diferentes','CPU/op não é CPU Docker nem duração HTTP')
    if 'cpu_distribuicao' in n:return ('Distribuição CPU Docker','Amostras reais de CPU da vítima (%)','victim_stats.metrics.cpu_percent','Boxplot por execução em [30,60)','A3/A4 e F2–F5 alcançam níveis elevados','Amostras temporais não são repetições independentes')
    if 'cpu_resumo' in n:return ('Resumo CPU Docker','Média, mediana e máximo amostrados','victim_stats.metrics.cpu_percent','Amostras em [30,60); sem IC','CPU média sobe com intensidade realizada antes do platô','Cadência real ~3 s; média não ponderada pelo tempo')
    if 'fracao_workers' in n:return ('Ocupação dos workers','Fração do tempo com 0, 1 e 2 workers','work_started/work_completed','Integração dos intervalos em [30,60)','Intensidades altas ocupam os dois workers quase todo o ataque','Não mede handlers HTTP ativos')
    if 'espera_worker' in n:return ('Espera por worker','Início computacional menos submissão (ms)','work_submitted/work_started','Boxplot por operação; bigodes p5–p95','A espera aumenta nas intensidades de maior acúmulo','Inclui IPC/escalonamento; não é espera HTTP total')
    if 'aguardando_matriz_escala_individual' in n:return ('Acúmulo computacional detalhado','Operações submetidas ainda não iniciadas','work_submitted/work_started','Reconstrução por eventos; eixo vertical individual','Revela variações pequenas ocultas pela escala comum','Escalas diferentes impedem comparação de altura direta; não é fila privada')
    if 'aguardando_matriz' in n or 'temporal_waiting' in n:return ('Acúmulo computacional temporal','Operações submetidas ainda não iniciadas','work_submitted/work_started','Reconstrução orientada a eventos; escala comum','A4 mantém acúmulo após 60 s; F2–F5 têm picos','Não é tamanho privado da fila do executor')
    if 'duracao_http_boxplot' in n:return ('Distribuição HTTP','Duração de respostas HTTP 200 (ms)','request_log.duration_ms','Somente respostas; boxplot p5–p95','Assimetria apresenta longas durações; Flooding alto também','Timeouts excluídos; em A4 restam somente 28 respostas')
    if 'duracao_http_ecdf' in n:return ('ECDF HTTP','Duração de respostas HTTP 200 (ms)','request_log.duration_ms','ECDF por execução','As caudas são observáveis sem combinar execuções','Timeouts excluídos, produzindo seleção de respostas em A4')
    if 'temporal_cpu' in n:return ('CPU temporal','CPU Docker da vítima (%)','victim_stats.jsonl','Timestamps reais, sem preenchimento','A4 tem residual de CPU após o ataque','Amostras espaçadas; coincidência temporal não prova causa')
    if 'temporal_running' in n:return ('Workers temporais','Workers em execução','work_started/work_completed','Reconstrução por eventos','A4 e F2–F5 mantêm dois workers ocupados','Não equivale à concorrência de clientes')
    if 'temporal_duration' in n:return ('Duração HTTP temporal','Duração individual no cliente (ms)','request_log','Pontos no instante de início HTTP','Durações sob estresse se prolongam','Timeout inclui tempo até encerramento, não resposta bem-sucedida')
    if 'relacoes_metricas' in n:return ('Relações exploratórias','RPS realizado versus CPU, ocupação e duração','processed/summary.csv, derivado de raw','Um ponto por execução','Exibe trajetórias descritivas por intensidade','Poucos pontos; sem inferência causal')
    if 'desfechos' in n:return ('Desfechos mutuamente exclusivos','HTTP 2xx, erro, timeout, falha e outro','request_log.outcome/http_status/error_type','Contagens da coorte iniciada em [30,60)','A3/A4 registraram timeouts; F1–F5, respostas 200','Não inclui tarefas submetidas antes do início HTTP')
    if 'fluxo_exclusivo' in n:return ('Partição das tarefas do Flooding','Resposta, erro, timeout, falha e sem início HTTP','source events/journal; request_log','Cada tarefa submetida em uma categoria exclusiva','F3–F5 concentram casos sem início HTTP','Sem início é expiração no gerador, não timeout da vítima')
    if 'intensidade_degradacao' in n:return ('Intensidade e atendimento','RPS nominal/efetivo e mediana HTTP','processed/summary.csv, derivado de raw','Painéis separados por unidade','Entrega F3–F5 não acompanha nominal crescente','Mediana apenas de respostas observadas')
    if 'etapas_gerador' in n:return ('Etapas do gerador','Submissões, inícios HTTP e diferença','diagnostics/source/events; journal','Contagens do ataque [30,60)','F3–F5 têm muitas submissões sem HTTP','Planejamento individual não observado; não chamar diferença de fila exata')
    if 'etapas_temporais' in n:return ('Etapas do gerador no tempo','Submissões, inícios e fins HTTP por segundo','diagnostics/source/events','Bins de 1 s por timestamp do evento','Mostra divergência temporal de etapas em F3–F5','Eventos posteriores a 60 s podem ser mostrados')
    if 'concorrencia_gerador' in n:return ('Concorrência do gerador','Tarefas entre task_started/task_finished','diagnostics/source/events','Reconstrução orientada a eventos','Permite comparar com limite configurado 64','Não é concorrência HTTP, pois inclui espera pré-HTTP')
    if 'taxas_temporais' in n:return ('HTTP temporal','Inícios e encerramentos por segundo','request_log','Bins semiabertos de 1 s','Términos após 60 s aparecem no pós-ataque','Não deduz causa a partir de defasagem')
    if 'rede_pacotes' in n:return ('Rede: pacotes','Linhas de captura TCP por segundo','traffic_capture.csv','Bins de 1 s','Volume acompanha tráfego observado','Retransmissões podem contar; não equivale a requisições')
    if 'rede_payload' in n:return ('Rede: payload TCP','Soma de packet_length por segundo (bytes)','traffic_capture.csv','Bins de 1 s; soma do campo primário','Volume aumenta com requisições realizadas','Não é byte on-wire/Ethernet nem payload HTTP único')
    if 'comparacao_descritiva' in n:return ('Entre mecanismos','RPS versus CPU, HTTP e ocupação','processed/summary.csv, derivado de raw','Painéis separados por unidade','Mecanismos ocupam faixas distintas de RPS e custo','Endpoints diferem; não é contraste causal')
    return ('Série exploratória','Métricas indicadas nos eixos','raw da execução correspondente','Critério descrito no gráfico','Revela comportamento da execução','Uma realização por configuração')

lines=['# B1 — caracterização exploratória dos mecanismos ofensivos','',
'## 1. Escopo e classificação','',
'O [inventário](inventario_execucoes.csv) contém 15 candidatas examinadas. O grupo principal reúne **oito execuções B1.2 completas**: A2–A4 (assimetria) e F1–F5 (Flooding), comparáveis descritivamente dentro de cada mecanismo. **A1** de B1.1 é um piloto complementar: foi recolhido antes e reutilizado pela B1.2 como referência; seus dados são processados e visualizados separadamente. Seis entradas foram excluídas do processamento B1: a tentativa preparatória `raw.attempt` sem raw final e cinco execuções combinadas/posteriores (B2-A, B2-F, B2-F96 e pilotos ambientais A3/F96 de 09/11). As cinco são experimentos válidos para outras perguntas, mas incluem tráfego legítimo, outra concorrência ou condição ambiental. Nenhuma execução completa B1 foi descartada por apresentar timeout ou saturação.', '',
'Os nove runs B1 possuem status `completed/simulation_end`, `producers_drained=true`, `errors=[]`, topologia direta, duas fontes ofensivas, nenhuma legítima, concorrência ofensiva agregada 64, dois workers persistentes, duração 150 s, ataque planejado em [30,60), endpoint `/expensive` para A e `/medium` para F. Diagnósticos, Docker stats e captura TCP estão presentes. Cada intensidade teve **uma realização**. O piloto A1 compartilha a configuração de base, mas pertence a coleta anterior e não foi somado à série principal.', '',
'## 2. Configuração e taxas verificadas nos registros primários','',
'| Run | Mecanismo | Endpoint | Fontes × RPS/fonte | Nominal | HTTP iniciado (RPS) | HTTP encerrado até 60 s (RPS) | Submetidas / sem início HTTP | 200 / timeout |',
'|---|---|---|---:|---:|---:|---:|---:|---:|']
for k in S.index:
    x=S.loc[k];lines.append(f'| {k}{" (piloto)" if k=="A1" else ""} | {x.mechanism} | {x.endpoint} | 2 × {int(x.rps_per_source)} | {int(x.nominal_rps)} | {x.rps_started:.3f} | {x.rps_finished_within:.3f} | {int(x.submitted)} / {int(x.not_http_started)} | {int(x.http_success)} / {int(x.timeouts)} |')
lines += ['', 'RPS iniciado = inícios HTTP com `elapsed_seconds` em [30,60) / 30 s. RPS encerrado = encerramentos com `end_elapsed_seconds` em [30,60) / 30 s; o denominador temporal é o mesmo, mas os eventos pertencem a etapas distintas. As tentativas iniciadas e encerradas após 60 s são preservadas em `processed/summary.csv`. `submitted` vem dos eventos dos geradores; `planned` individual não foi registrado nessas fontes e aparece como ausência, não como zero planejado. Em F3–F5, a diferença entre submetidas e inícios corresponde aos registros `abandoned_admission` nos journals. Todas as requisições com início HTTP têm encerramento observado; A3 e A4 incluem timeouts do cliente, não respostas bem-sucedidas.', '',
'## 3. Métricas e relógios','',
'Os tempos HTTP do cliente usam `request_log.elapsed_seconds`/`end_elapsed_seconds`, relativos ao início monotônico do run. Os eventos da vítima trazem `work_submitted`, `work_started`, `work_completed`, `handler_started` e `handler_finished`, correlacionados por `operation_id` e `request_id`; eventos de auditoria anteriores à execução foram excluídos. Os workers usam `CLOCK_MONOTONIC` no mesmo namespace observado na vítima. O relógio de Docker stats usa `monotonic` menos `experiment_start_monotonic`. A linha de captura TCP usa `elapsed_seconds` relativo ao mesmo run. As séries são alinháveis como tempo relativo, mas diferenças de cadência e de estágio impedem equiparar eventos.', '',
'CPU Docker é `metrics.cpu_percent` do contêiner `target_instance_1` (%; 100% ≈ um núcleo lógico). Memória é `metrics.raw_mem_usage / 2²⁰` MiB do contêiner. CPU/op é `work_cpu_seconds × 1000` ms do processo worker; duração de execução computacional é `work_completed.at − work_started.at`; espera por worker é `work_started.at − work_submitted.at`, incluindo IPC/escalonamento. Trabalhadores ocupados e operações aguardando são estados reconstruídos desses eventos. HTTP ativo é intervalo de início até encerramento **no cliente**, inclusive até timeout. `packet_length` da captura é comprimento de payload TCP do resumo, não tamanho de quadro Ethernet ou bytes HTTP únicos. Nenhum valor ausente foi imputado.', '',
'## 4. Assimetria: achados descritivos','',
f'A2, A3 e A4 tiveram RPS iniciado {v("A2","rps_started",3)}, {v("A3","rps_started",3)} e {v("A4","rps_started",3)} frente a 4, 8 e 16 nominais. A CPU Docker média no ataque foi {v("A2","cpu_mean",1)}%, {v("A3","cpu_mean",1)}% e {v("A4","cpu_mean",1)}%. A fração de [30,60) com dois workers ocupados passou de {v("A2","workers_2_fraction",3)} para {v("A3","workers_2_fraction",3)} e {v("A4","workers_2_fraction",3)}. Picos de operações aguardando: {int(S.loc["A2","waiting_max"])}, {int(S.loc["A3","waiting_max"])} e {int(S.loc["A4","waiting_max"])}. Os timeouts foram 0, 38 e 453; em A4 restaram apenas 28 respostas HTTP 200 para a distribuição de duração. O residual computacional de A4 terminou em t={V["runs"]["A4"]["last_work_finish_s"]:.3f} s, depois do fim do ataque. Não se deve usar duração de timeout como duração de resposta.', '',
'A1 (piloto) tinha 2 RPS nominais e 2,067 RPS iniciados; está em figura adicional e não forma uma repetição da intensidade A2. A CPU/op, a espera e a duração podem variar com a intensidade realizada e o acúmulo, mas não se atribui a diferença a um único componente sem controle adicional.', '',
'## 5. Flooding: achados descritivos','',
f'F1–F5 receberam 32, 64, 128, 192 e 256 RPS nominais. Iniciaram {v("F1","rps_started",3)}, {v("F2","rps_started",3)}, {v("F3","rps_started",3)}, {v("F4","rps_started",3)} e {v("F5","rps_started",3)} RPS. A fração realizado/nominal caiu após F2: {v("F2","efficiency_rps",3)}, {v("F3","efficiency_rps",3)}, {v("F4","efficiency_rps",3)}, {v("F5","efficiency_rps",3)}. F3–F5 tiveram {int(S.loc["F3","not_http_started"])}, {int(S.loc["F4","not_http_started"])} e {int(S.loc["F5","not_http_started"])} tarefas submetidas sem início HTTP, confirmadas por `abandoned_admission`. O máximo de tarefas ativas no gerador e as durações HTTP estão em `processed/summary.csv`; tarefas ativas não são HTTP simultâneos. Todas as tentativas que iniciaram HTTP obtiveram resposta 200, ainda que a duração tenha aumentado. Assim, a limitação observada inclui estágio pré-HTTP no gerador; a causa única não foi isolada.', '',
'## 6. Comparação entre mecanismos','',
'A figura conjunta usa painéis por unidade e rótulos de mecanismo/endpoint. `/expensive` executa operação computacional mais custosa que `/medium`; as intensidades nominais e realizadas ocupam faixas distintas. As curvas são apenas uma organização descritiva das execuções, sem comparação causal de eficácia. A ausência de tráfego legítimo em todos os nove runs também impede extrapolar diretamente a degradação de clientes legítimos.', '',
'## 7. Catálogo das figuras','',
'Cada linha representa um PNG; há PDF vetorial homônimo. O arquivo é linkável, e `manifest.json` lista todas as saídas.','',
'| Figura | Objetivo | Fonte e método | Observação | Limite |','|---|---|---|---|---|']
for path in M['figures']:
    if not path.endswith('.png'):continue
    title,metric,source,method,obs,limit=typ(path)
    lines.append(f'| [{Path(path).name}]({path}) | {title}: {metric} | {source}; {method} | {obs} | {limit} |')
lines += ['',
'## 8. Validação e limitações','',
f'Foram geradas {V["figure_pairs"]} figuras PNG/PDF. A validação confere hashes dos arquivos primários lidos, IDs, contagens, estados dos workers e figuras. O processo não altera datasets. As amostras Docker têm cadência real próxima de 3 s, apesar de polling configurado em 1 s; os painéis mostram pontos reais, sem preencher lacunas. Percentis por execução são descritivos, sem IC ou teste inferencial. A4 possui seleção extrema de respostas bem-sucedidas. Os eventos `work_completed` após o fim do ataque mostram que fim do período ofensivo não significa fim imediato do trabalho da vítima. Não há medição direta da fila HTTP pré-handler nem da profundidade privada do executor.', '',
'O ambiente foi recriado entre execuções; condições não observadas do host podem variar. A campanha B1.1 difere da B1.2 no propósito/estágio. Dentro da B1.2 existe uma execução por intensidade. A concorrência ofensiva foi 64 em todas as nove execuções, mas isso não garante 64 tarefas HTTP ativas. Não há planos individuais `planned` nos geradores ofensivos; não se produz taxa planejada medida. Os bytes de captura não são tráfego on-wire. O inventário registra separadamente as campanhas combinadas e pilotos posteriores, sem usá-los para completar B1.', '',
'## 9. Síntese para decisão científica posterior','',
'Os registros sustentam duas descrições: na assimetria, intensidades realizadas maiores vieram acompanhadas de maior ocupação, acúmulo e timeouts; no Flooding, o RPS HTTP iniciado deixou de acompanhar a intensidade nominal acima de F2 e surgiram expirações antes do HTTP. São características observadas nesta campanha isolada, não provas de superioridade de um mecanismo ou explicação causal única. A seleção das figuras para o TCC e a interpretação de por que F96/96 foi posteriormente adotado apesar da recomendação histórica F2/64 permanecem decisões científicas separadas.', '',
'## 10. Reprodução','',
'Na raiz do repositório, com Python 3, `numpy`, `pandas`, `matplotlib` e `Pillow` (validação):','',
'```bash','python3 reports/b1_attack_characterization_20261112/scripts/generate.py','python3 reports/b1_attack_characterization_20261112/scripts/write_report.py','python3 reports/b1_attack_characterization_20261112/scripts/validate.py','```','',
'Entradas: somente B1.1 A1 e B1.2 A2–A4/F1–F5. Parâmetros: run [0,150), ataque [30,60), bins de 1 s para taxas/rede, timestamps reais para Docker e eventos. Código versionado pelo SHA-256 em `manifest.json`. Saídas em `processed/`, `figures/`, `validation/`, inventário e este relatório.']
detail=['### Resumo computacional e de atendimento por execução','',
'| Run | CPU Docker média / máximo (%) | Memória média (MiB) | CPU worker média / p95 (ms/op) | Espera worker mediana / p95 (ms) | HTTP 200 mediana / p95 (ms) | Máx. aguardando / tarefas ativas no gerador |',
'|---|---:|---:|---:|---:|---:|---:|']
for k in S.index:
    x=S.loc[k]
    detail.append(f'| {k} | {x.cpu_mean:.1f} / {x.cpu_max:.1f} | {x.mem_mean_mib:.2f} | {x.worker_cpu_mean_ms:.1f} / {x.worker_cpu_p95_ms:.1f} | {x.worker_wait_median_ms:.1f} / {x.worker_wait_p95_ms:.1f} | {x.http_median_ms:.1f} / {x.http_p95_ms:.1f} | {int(x.waiting_max)} / {int(x.source_concurrency_max)} |')
detail += ['', 'CPU Docker e memória usam as amostras reais em [30,60). CPU/op e espera usam ciclos completos de trabalho correlacionados à execução. Duração HTTP usa **somente respostas 200**; em A4 são 28, de modo que o p95 é um extremo empírico frágil. A coluna de tarefas ativas mede `task_started`–`task_finished` no gerador, incluindo tempo pré-HTTP; seu limite configurado é 64.', '']
pos=lines.index('## 4. Assimetria: achados descritivos')
lines[pos:pos]=detail
(OUT/'relatorio.md').write_text('\n'.join(lines),encoding='utf-8')
(OUT/'README.md').write_text('# Caracterização ofensiva B1\n\nInventário, séries processadas, painéis individuais e comparações para assimetria e HTTP Request Flooding. Consulte [relatorio.md](relatorio.md), [inventario_execucoes.csv](inventario_execucoes.csv) e [manifest.json](manifest.json).\n\nReprodução na raiz do repositório:\n\n```bash\npython3 reports/b1_attack_characterization_20261112/scripts/generate.py\npython3 reports/b1_attack_characterization_20261112/scripts/write_report.py\npython3 reports/b1_attack_characterization_20261112/scripts/validate.py\n```\n\nDependências: Python 3, numpy, pandas, matplotlib e Pillow.\n',encoding='utf-8')
